query getThematicPlans(
    $investorId: ID
    $perPage: Int
    $currentPage: Int
    $searchBy: String
    $sortColumn: String
    $sortDirection: String
    $filter: GoalPlansFilter
  ) {
    getThematicPlans(
      investorId: $investorId
      perPage: $perPage
      currentPage: $currentPage
      searchBy: $searchBy
      sortColumn: $sortColumn
      sortDirection: $sortDirection
      filter: $filter
    ) {
      data {
        id
        goalName
        clientStrategyDisplayName
        initialInvestmentAmount
        monthlyInvestmentAmount
        status
        riskProfile
        currency {
          name
        }
        activityType
        activityStatus
        investmentRequestStatus
        investmentStatus
        parentCtrStatus
        proposalStatus
        createdAt
        strategyId
        strategyVersionId
        recurringInvestmentDetails {
          customDebitDate
          debitDate
          frequency
        }
        childCtrStatus {
          id
          status
        }
        investorId
        investorReferenceId
        ddaMandateStatus
        expectedReturn {
          id
          outcome {
            month
            datum {
              amount
              probabilityPercentage
            }
          }
        }
      }
      meta {
        totalCount
        perPage
        currentPage
      }
    }
  }

